D=dict(unit_id=plan['id'],package_file=target.name,session_ids=[s['id'] for s in S],new_lexemes=[dict(**{k:W[w][k] for k in ['id','lexeme_key','fr','ru','transcription_ru']},first_session_id=S[n-1]['id']) for w,n in FIRST.items()],reused_lexeme_keys=sorted({w['lexeme_key'] for s in S for w in s['vocabulary'] if w['id'] in OLD}),objective_coverage=coverage,
 review_targets_for_next_unit=[dict(lexeme_key=W[w]['lexeme_key'],reason=r) for w,r in [('autrefois','Повторить явное отнесение обстоятельств к прошлому.'),('pendant-que','Сохранить отношение одновременности отдельно от условия или причины.'),('souvenir','Вернуть короткое воспоминание как тип рассказа.'),('un-jour','Повторить отдельный случай прошлого.'),('quand-jetais-enfant','Вернуть изученную рамку детского периода без расширения до всех форм.'),('jai-age','Сохранить старый ключ возраста при смене грамматической формы.'),('jai-possession','Сохранить старый ключ наличия вещи при смене формы.'),('regarder','Повторить знакомое действие в изученных временных моделях.'),('maintenant','Сохранить явно названное настоящее отдельно от прежнего периода.')]],
 checks=dict(json_parsed=False,schema_validated=False,site_preview_passed=False,browser_audio_checked=False,language_reviewed_by_human=False),
 open_issues=['Для импорта требуется A2-U03-L05 в целевой базе; текущий пакет не создаёт внешнюю зависимость.','Редактору проверить естественность воспоминаний, смысловое противопоставление фона, привычки и события, уместность дозировки выбранных форм.','Прослушать браузерную озвучку J’avais / J’ai, J’étais, regardais / regarde, временной связки и выбранного возвращения брата. Длительность аудио и занятий не измерена.','Выполнить предпросмотр и пробное прохождение: разные возраста и места в разных текстах, одновременность и последовательность, сравнение прошлого и настоящего без лишних выводов.'],
 progress=dict(current_unit=plan['id'],prepared_session_ids=[s['id'] for s in S],user_accepted_session_ids=[],remaining_session_ids=[],next_unit_not_started='A2-U05',next_unit_title='Планы и намерения',previous_unit='A2-U03',previous_unit_advance_authorized=True,previous_unit_import_confirmed=False),
 scope_notes=['Команда «Следующий этап» разрешает подготовку A2-U04. Принятие и импорт предыдущих пакетов не подтверждены; повторение использует полные объекты подготовленного материала.','Новые лексические значения распределены как два, два, одно, ноль и ноль. Небольшой словарь оставляет нагрузку для новой грамматики и смыслового контраста. L05 нового обязательного материала не вводит.','J’avais как прежний возраст использует fr:jai:age-frame, а как наличие вещи — fr:jai:possession. Новая временная форма не создаёт дублирующих лексических значений. Полные прежние объекты слов не переписываются.','Souvenir учится как воспоминание, не как сувенир-предмет. Un jour здесь вводит отдельный случай в рассказе о прошлом, не все возможные употребления этого сочетания.','Autrefois задаёт прежний период. Новая готовая рамка quand j’étais enfant вводит детство; существующее quand как вопрос о времени сохраняет свой смысл и не переписывается.','В рамке детства j’étais выражает состояние, а не вспомогательную часть passé composé. Старый être-pc используется только в завершённом возвращении, не присваивается фоновому состоянию.','Вводятся выбранные формы j’avais, j’étais и je regardais без полной таблицы imparfait. Новое прошедшее время сопоставляется с уже введёнными завершёнными событиями.','Фон, привычка и отдельное событие распознаются по смыслу контекста. Не вводится ложное правило любое долгое действие — imparfait или любое короткое — passé composé. Не утверждается, что фоновое действие обязательно осталось незавершённым навсегда.','Souvent и описание периода помогают распознать прежнюю привычку. Та же форма je regardais в отдельном эпизоде описывает происходивший просмотр. Это разные функции в конкретных текстах.','Pendant que выражает одновременность. Просмотр не объявляется причиной возвращения и не считается автоматически прерванным. Puis отдельно сохраняет прежний смысл последовательности.','Mon frère est rentré — выбранная форма знакомого завершённого возвращения с названным братом; весь ряд новых лиц и глаголов не вводится одновременно.','В L04 и L05 прежние и нынешние привычки сопоставлены явно. Из одного прошлого описания не выводится, что привычка обязательно исчезла или что предмета теперь нет.','В L01 повторена последовательность завершённых действий A2-U03. В L03/L04 возвращаются проживание и багаж A2-U01. Это не подтверждает принятие прошлых пакетов или освоение материала учеником.','Каждый текст — отдельное оригинальное воспоминание. Возраст, место просмотра и состав обстоятельств меняются между заданиями. Относительные периоды не привязаны к текущему календарю сайта.','Все ответы выбираются или собираются из целых блоков. Нет обязательного свободного письма или записи голоса; озвучка только браузером.','Пакет содержит только текущую тему, без levels и curricula. Основной реестр, прежние пакеты и база сайта не изменялись.'])
